@Repository
@Transactional
public class JpaItemRepositoryV3 implements ItemRepository {

    private final ItemJpaRepository repository;   // Data JPA
    private final JPAQueryFactory query;          // Querydsl

    public JpaItemRepositoryV3(ItemJpaRepository repository, EntityManager em) {
        this.repository = repository;
        this.query = new JPAQueryFactory(em);
    }

    @Override
    public Item save(Item item) {
        return repository.save(item);
    }

    @Override
    public void update(Long itemId, ItemUpdateDto updateParam) {
        Item findItem = repository.findById(itemId).orElseThrow();
        findItem.setItemName(updateParam.getItemName());
        findItem.setPrice(updateParam.getPrice());
        findItem.setQuantity(updateParam.getQuantity());
    }

    @Override
    public Optional<Item> findById(Long id) {
        return repository.findById(id);
    }

    @Override
    public List<Item> findAll(ItemSearchCond cond) {
        return query
                .selectFrom(item)
                .where(likeItemName(cond.getItemName()),
                       maxPrice(cond.getMaxPrice()))
                .fetch();
    }
}

// 1. 조회 인터페이스
public interface ItemRepositoryCustom {
    List<Item> search(ItemSearchCond cond);
}

// 2. Querydsl 구현
@RequiredArgsConstructor
public class ItemRepositoryImpl implements ItemRepositoryCustom {

    private final JPAQueryFactory query;

    @Override
    public List<Item> search(ItemSearchCond cond) {
        return query.selectFrom(item)
                .where(likeItemName(cond.getItemName()),
                       maxPrice(cond.getMaxPrice()))
                .fetch();
    }

    private BooleanExpression likeItemName(String itemName) {
        return StringUtils.hasText(itemName)
                ? item.itemName.like("%" + itemName + "%") : null;
    }

    private BooleanExpression maxPrice(Integer maxPrice) {
        return maxPrice != null ? item.price.loe(maxPrice) : null;
    }
}

// 3. 합친다
public interface ItemRepository
        extends JpaRepository<Item, Long>, ItemRepositoryCustom {
}

